import{_ as e,o as d,c as l,a5 as a}from"./chunks/framework.D47SInms.js";const g=JSON.parse('{"title":"ROS 2 서비스 레퍼런스","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/ros/services.md","filePath":"ko/software/sdk/ros/services.md","lastUpdated":1791600043000}'),o={name:"ko/software/sdk/ros/services.md"};function s(r,t,i,c,n,h){return d(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="ros-2-서비스-레퍼런스" tabindex="-1">ROS 2 서비스 레퍼런스 <a class="header-anchor" href="#ros-2-서비스-레퍼런스" aria-label="Permalink to &quot;ROS 2 서비스 레퍼런스&quot;">​</a></h1><p>로봇 소프트웨어가 CycloneDDS로 제공하는 ROS 2 서비스의 레퍼런스입니다.</p><p><a href="/RBQ/nightly/ko/software/sdk/ros/topics.html">토픽</a>과 마찬가지로 별도 드라이버 노드가 필요 없습니다. 로봇의 각 프로세스가 ROS 2 호환 DDS로 서비스를 직접 제공하므로, 프로세스가 실행 중이면 <code>ros2 service list</code>와 <code>ros2 service call</code>을 바로 쓸 수 있습니다. <code>RMW_IMPLEMENTATION=rmw_cyclonedds_cpp</code>와 네트워크 인터페이스는 토픽과 같게 맞춥니다(<a href="/RBQ/nightly/ko/software/sdk/ros/network.html">네트워크 &amp; DDS</a> 참고).</p><p>모든 서비스는 표준 <code>rcl_interfaces</code> 타입 두 가지만 쓰므로 별도 워크스페이스가 필요 없습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">타입</th><th style="text-align:left;">쓰는 곳</th></tr></thead><tbody><tr><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td><td style="text-align:left;"><code>set_param</code> — 값 설정, <code>set_service</code> — 동작 실행·기능 전환</td></tr><tr><td style="text-align:left;"><code>rcl_interfaces/srv/GetParameters</code></td><td style="text-align:left;"><code>get_param</code> — 값 읽기</td></tr></tbody></table><h2 id="rules" tabindex="-1">요청·응답 규칙 <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;요청·응답 규칙 {#rules}&quot;">​</a></h2><ul><li><strong>파라미터마다 결과가 하나입니다.</strong> <code>SetParameters</code>는 <code>parameters[i]</code>마다 <code>results[i]</code>를 같은 순서로 돌려줍니다. 실패는 파라미터 단위라서, 한 요청 안의 다른 파라미터는 그대로 적용됩니다.</li><li><strong>실패 사유.</strong> 실패한 항목은 <code>successful: false</code>와 짧은 영어 <code>reason</code>(예: <code>unknown parameter</code>, <code>expects number</code>)을 담습니다. 성공한 항목의 <code>reason</code>은 비어 있습니다.</li><li><strong>요청당 파라미터는 64개까지입니다.</strong> 넘으면 요청 전체를 거부합니다. <code>set_*</code>는 모든 항목이 <code>too many parameters (max 64)</code>로 실패하고, <code>get_param</code>은 모든 값이 미설정으로 돌아옵니다.</li><li><strong>값 타입.</strong> <code>value.type</code>을 명시합니다(<code>1</code>=bool, <code>2</code>=정수, <code>3</code>=실수, <code>4</code>=문자열). <code>0</code>으로 두면 로봇이 채워진 값 필드 하나를 골라 씁니다. 다만 0 값(<code>0</code>, <code>0.0</code>, 빈 문자열)은 이렇게 판별할 수 없으므로, 0을 보낼 때는 반드시 타입을 지정합니다.</li><li><strong><code>get_param</code>에 없는 이름</strong>은 <code>type: 0</code>(미설정)으로 돌아옵니다.</li><li><strong><code>set_service</code>는 bool 값을 받습니다.</strong> 이름에 따로 적힌 경우(<code>gait</code>, <code>stream_live</code>)만 예외입니다. <em>true만</em> 표시된 항목에 <code>false</code>를 보내면 <code>true only</code>로 실패합니다.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">서비스</th><th style="text-align:left;">프로세스</th><th style="text-align:left;">사용 조건</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="#motion"><code>/rbq/motion/*</code></a></td><td style="text-align:left;"><code>Network</code></td><td style="text-align:left;">로봇 소프트웨어 실행 중</td></tr><tr><td style="text-align:left;"><a href="#vision"><code>/rbq/vision/*</code></a></td><td style="text-align:left;"><code>Streamer</code></td><td style="text-align:left;">비전 소프트웨어 실행 중</td></tr><tr><td style="text-align:left;"><a href="#camera"><code>/rbq/camera/*</code></a></td><td style="text-align:left;"><code>HAL</code></td><td style="text-align:left;">비전 소프트웨어 실행 중</td></tr><tr><td style="text-align:left;"><a href="#ptz"><code>/rbq/ptz/*</code></a></td><td style="text-align:left;"><code>Ptz</code></td><td style="text-align:left;"><a href="/RBQ/nightly/ko/manual/related-products/ptz-camera.html">PTZ 카메라 페이로드</a> 장착 시</td></tr></tbody></table><h2 id="motion" tabindex="-1">모션 <a class="header-anchor" href="#motion" aria-label="Permalink to &quot;모션 {#motion}&quot;">​</a></h2><h3 id="rbq-motion-set-param" tabindex="-1"><code>/rbq/motion/set_param</code> <a class="header-anchor" href="#rbq-motion-set-param" aria-label="Permalink to &quot;`/rbq/motion/set_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">페이로드·보행·도킹 파라미터를 설정합니다. 값은 모두 숫자(정수 또는 실수)입니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">단위</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>payload.mass</code></td><td style="text-align:left;">kg</td><td style="text-align:left;">추가 페이로드 질량. 무게중심 보상에 씁니다</td></tr><tr><td style="text-align:left;"><code>payload.com_x</code> / <code>payload.com_y</code> / <code>payload.com_z</code></td><td style="text-align:left;">m</td><td style="text-align:left;">페이로드 무게중심(몸체 기준)</td></tr><tr><td style="text-align:left;"><code>dynamics.max_speed</code></td><td style="text-align:left;">m/s</td><td style="text-align:left;">보행 속도 상한</td></tr><tr><td style="text-align:left;"><code>dynamics.body_height</code></td><td style="text-align:left;">m</td><td style="text-align:left;">기본 자세 대비 서 있는 높이 오프셋</td></tr><tr><td style="text-align:left;"><code>dynamics.body_tilt</code></td><td style="text-align:left;">deg</td><td style="text-align:left;">보행 중 몸체 고정 피치</td></tr><tr><td style="text-align:left;"><code>dock.offset_x</code> / <code>dock.offset_y</code></td><td style="text-align:left;">m</td><td style="text-align:left;">도킹 목표 오프셋</td></tr><tr><td style="text-align:left;"><code>dock.count_req</code></td><td style="text-align:left;">—</td><td style="text-align:left;">도킹 전 마커 검출 시도 횟수</td></tr><tr><td style="text-align:left;"><code>dock.count_try</code></td><td style="text-align:left;">—</td><td style="text-align:left;">포기하기 전까지 허용하는 도킹 실패 횟수</td></tr></tbody></table><p><code>dynamics.*</code>의 범위는 앱의 <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html#drive-parameters">주행 파라미터</a>와 같습니다. <code>payload.*</code> 값이 페이로드 한계를 벗어나면 <code>reason: validation_error</code>로 실패합니다. 무게중심 한계는 |x| ≤ 0.5 m, |y| ≤ 0.3 m, |z| ≤ 0.4 m이고, 질량 한계는 로봇 모델에 따라 다릅니다.</p><div class="warning custom-block"><p class="custom-block-title"><code>dynamics.max_speed</code>를 먼저 설정하세요</p><p>로봇은 <code>dynamics.*</code> 세 값을 한꺼번에 적용합니다. <code>dynamics.max_speed</code>를 한 번도 설정하지 않았으면 <code>body_height</code>와 <code>body_tilt</code>는 <code>dynamics.max_speed not set yet - set it first</code>로 실패합니다. 세 값을 한 요청에 함께 보내는 것이 안전합니다. 저장된 값은 로봇 소프트웨어가 재시작되면 초기화됩니다.</p></div><p><code>payload.*</code>는 첫 번째 사용자 페이로드 슬롯을 설정합니다.</p><h3 id="rbq-motion-get-param" tabindex="-1"><code>/rbq/motion/get_param</code> <a class="header-anchor" href="#rbq-motion-get-param" aria-label="Permalink to &quot;`/rbq/motion/get_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/GetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">위 <code>set_param</code> 이름의 현재 값을 읽습니다. 값은 실수(<code>type: 3</code>)로 돌아옵니다.</td></tr></tbody></table><p><code>dynamics.max_speed</code>는 <code>set_param</code>으로 설정하기 전까지 미설정으로 돌아옵니다.</p><h3 id="rbq-motion-set-service" tabindex="-1"><code>/rbq/motion/set_service</code> <a class="header-anchor" href="#rbq-motion-set-service" aria-label="Permalink to &quot;`/rbq/motion/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">모션 동작을 실행하고 모드를 전환합니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">값</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>estop</code></td><td style="text-align:left;">bool, <em>true만</em></td><td style="text-align:left;">비상 정지 — 모든 관절이 고댐핑 상태가 됩니다. <strong>로봇이 주저앉습니다.</strong> <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#rbq-cmd-emergency"><code>/rbq/cmd/emergency</code></a>와 같습니다</td></tr><tr><td style="text-align:left;"><code>auto_start</code></td><td style="text-align:left;">bool, <em>true만</em></td><td style="text-align:left;">CAN 확인 → Find Home → Control Start. <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#rbq-cmd-auto-start"><code>/rbq/cmd/auto_start</code></a>와 같습니다</td></tr><tr><td style="text-align:left;"><code>control_mode</code></td><td style="text-align:left;">bool</td><td style="text-align:left;"><code>true</code> → HighLevel Command 모드, <code>false</code> → 조이스틱 모드. <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#rbq-cmd-switch-control-mode"><code>/rbq/cmd/switch_control_mode</code></a>와 같습니다</td></tr><tr><td style="text-align:left;"><code>power_ch&lt;N&gt;</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">PDU 전원 포트 <code>N</code>(<code>0</code>~<code>31</code>)을 켜거나 끕니다. 포트 번호는 <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#power-control">전원 제어</a>에 있습니다</td></tr><tr><td style="text-align:left;"><code>gait</code></td><td style="text-align:left;">정수 또는 문자열</td><td style="text-align:left;">Gait를 전환합니다. 정수는 <a href="/RBQ/nightly/ko/software/sdk/ros/reference.html#gait-state-id">Gait State ID</a>의 id, 문자열은 아래 이름 중 하나입니다</td></tr></tbody></table><p><code>gait</code>가 받는 이름(대소문자 무관): <code>sitting</code>, <code>standing</code>, <code>aiming</code>, <code>trotting</code>, <code>trot_stairs</code>, <code>waving</code>, <code>trot_running</code>, <code>docking</code>, <code>rl_trot</code>, <code>rl_front_walk</code>, <code>rl_left_walk</code>, <code>rl_right_walk</code>, <code>rl_bound</code>, <code>rl_pace</code>, <code>rl_pronk</code>, <code>rl_3leg_hr</code>, <code>rl_trot_vision</code>, <code>rl_trot_run</code>, <code>rl_silent</code>, <code>rl_trot_vision_slow</code>, <code>rl_walk</code>, <code>rl_walk_vision</code>. 그 밖의 id나 이름은 <code>unknown gait id</code> / <code>unknown gait name</code>으로 실패합니다.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>estop</code>은 관절 토크를 즉시 끊어 로봇이 넘어집니다. 시험할 때는 로봇을 먼저 앉히세요.</p></div><p><strong>예시:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 보행 파라미터 — 세 값을 함께 보냅니다</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/motion/set_param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rcl_interfaces/srv/SetParameters</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;{parameters: [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    {name: &#39;dynamics.max_speed&#39;,   value: {type: 3, double_value: 1.0}},</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    {name: &#39;dynamics.body_height&#39;, value: {type: 3, double_value: 0.0}},</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    {name: &#39;dynamics.body_tilt&#39;,   value: {type: 3, double_value: 0.0}}]}&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 페이로드 질량 읽기</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/motion/get_param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rcl_interfaces/srv/GetParameters</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{names: [&#39;payload.mass&#39;]}&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 이름으로 서기 자세 전환</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/motion/set_service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rcl_interfaces/srv/SetParameters</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;{parameters: [{name: &#39;gait&#39;, value: {type: 4, string_value: &#39;standing&#39;}}]}&quot;</span></span></code></pre></div><h2 id="vision" tabindex="-1">비전 <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;비전 {#vision}&quot;">​</a></h2><h3 id="rbq-vision-set-param-·-rbq-vision-get-param" tabindex="-1"><code>/rbq/vision/set_param</code> · <code>/rbq/vision/get_param</code> <a class="header-anchor" href="#rbq-vision-set-param-·-rbq-vision-get-param" aria-label="Permalink to &quot;`/rbq/vision/set_param` · `/rbq/vision/get_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code> · <code>rcl_interfaces/srv/GetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">WebRTC 영상 스트림 설정입니다. 바꾼 값은 재시작 후에도 유지됩니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">값</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>webrtc.width</code> / <code>webrtc.height</code></td><td style="text-align:left;">정수, <code>16</code>~<code>7680</code></td><td style="text-align:left;">스트림 해상도(픽셀). 하나만 바꾸면 다른 하나는 그대로입니다</td></tr><tr><td style="text-align:left;"><code>webrtc.preset</code></td><td style="text-align:left;">문자열</td><td style="text-align:left;">x264 인코더 프리셋: <code>ultrafast</code>, <code>superfast</code>, <code>veryfast</code>, <code>faster</code>, <code>fast</code>, <code>medium</code>, <code>slow</code>, <code>slower</code>, <code>veryslow</code>, <code>placebo</code></td></tr></tbody></table><h3 id="rbq-vision-set-service" tabindex="-1"><code>/rbq/vision/set_service</code> <a class="header-anchor" href="#rbq-vision-set-service" aria-label="Permalink to &quot;`/rbq/vision/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">비전 기능과 라이브 뷰를 전환합니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">값</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>stream_live</code></td><td style="text-align:left;">정수</td><td style="text-align:left;">라이브 뷰를 id로 선택합니다 — <code>0</code> 없음, <code>1</code> 전방, <code>2</code> 후방, <code>3</code> 좌측, <code>4</code> 우측, <code>11</code> 스택, <code>12</code> 파노라마, <code>13</code> 계단, <code>14</code> 좌우 나란히, <code>15</code> 도킹</td></tr><tr><td style="text-align:left;"><code>face_detect</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">얼굴 검출 오버레이</td></tr><tr><td style="text-align:left;"><code>point2go</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Point-to-go 오버레이</td></tr><tr><td style="text-align:left;"><code>guide</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">가이드 오버레이</td></tr><tr><td style="text-align:left;"><code>day</code></td><td style="text-align:left;">bool</td><td style="text-align:left;"><code>true</code> → 주간 모드, <code>false</code> → 야간(IR) 모드</td></tr><tr><td style="text-align:left;"><code>heightmap.stairs</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">높이 맵 계단 검출</td></tr><tr><td style="text-align:left;"><code>heightmap.edge</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">높이 맵 모서리 검출</td></tr><tr><td style="text-align:left;"><code>heightmap.align</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">높이 맵을 몸체 yaw에 맞춰 정렬</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>stream_live: 0</code>(뷰 없음)은 다른 시청자가 스트림을 보고 있으면 성공으로 응답하지만 실제로는 무시됩니다.</p></div><h2 id="camera" tabindex="-1">카메라 <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;카메라 {#camera}&quot;">​</a></h2><h3 id="rbq-camera-set-param-·-rbq-camera-get-param" tabindex="-1"><code>/rbq/camera/set_param</code> · <code>/rbq/camera/get_param</code> <a class="header-anchor" href="#rbq-camera-set-param-·-rbq-camera-get-param" aria-label="Permalink to &quot;`/rbq/camera/set_param` · `/rbq/camera/get_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code> · <code>rcl_interfaces/srv/GetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">카메라 설정을 <code>&lt;SECTION&gt;.&lt;key&gt;</code> 이름으로 읽고 씁니다. 예: <code>MAIN.RS_PRESET_HIGH_DENSITY</code></td></tr></tbody></table><ul><li><code>set_param</code>은 이미 있는 키만 바꿉니다. 오타는 <code>unknown section</code> 또는 <code>unknown key</code>로 실패합니다. 스칼라 값이면 무엇이든 받아 텍스트로 저장하고, 변경에 성공하면 카메라 설정을 다시 불러옵니다.</li><li><code>get_param</code>은 저장된 텍스트(<code>type: 4</code>)를 돌려주고, 키가 없으면 미설정으로 돌려줍니다.</li></ul><h3 id="rbq-camera-set-service" tabindex="-1"><code>/rbq/camera/set_service</code> <a class="header-anchor" href="#rbq-camera-set-service" aria-label="Permalink to &quot;`/rbq/camera/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">카메라 동작입니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">값</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ir_projector</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">모든 깊이 카메라의 IR 프로젝터를 켜거나 끕니다</td></tr><tr><td style="text-align:left;"><code>reload_config</code></td><td style="text-align:left;">bool, <em>true만</em></td><td style="text-align:left;">카메라 설정을 다시 불러옵니다</td></tr><tr><td style="text-align:left;"><code>sensor_&lt;N&gt;.enabled</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">카메라 센서 <code>N</code>을 엽니다(<code>true</code>) 또는 닫습니다(<code>false</code>). 센서 id는 <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#vision-camera-sensors">비전 — 카메라 센서</a>에 있습니다</td></tr></tbody></table><h2 id="ptz" tabindex="-1">PTZ <a class="header-anchor" href="#ptz" aria-label="Permalink to &quot;PTZ {#ptz}&quot;">​</a></h2><h3 id="rbq-ptz-set-param" tabindex="-1"><code>/rbq/ptz/set_param</code> <a class="header-anchor" href="#rbq-ptz-set-param" aria-label="Permalink to &quot;`/rbq/ptz/set_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">PTZ 위치와 속도입니다. 값은 모두 숫자입니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">단위</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pan</code> / <code>tilt</code></td><td style="text-align:left;">rad</td><td style="text-align:left;">목표 각도. 범위는 <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#vision-ptz-camera"><code>/rbq/cmd/ptz</code></a>와 같습니다</td></tr><tr><td style="text-align:left;"><code>zoom</code></td><td style="text-align:left;">×</td><td style="text-align:left;">목표 줌. 범위는 <code>/rbq/cmd/ptz</code>와 같습니다</td></tr><tr><td style="text-align:left;"><code>pan_vel</code> / <code>tilt_vel</code></td><td style="text-align:left;">deg/s</td><td style="text-align:left;">이 속도로 회전합니다</td></tr><tr><td style="text-align:left;"><code>zoom_vel</code></td><td style="text-align:left;">—</td><td style="text-align:left;">이 비율로 연속 줌합니다</td></tr></tbody></table><p><code>/rbq/cmd/ptz</code>와 달리 이름마다 따로 적용됩니다. <code>pan</code>만 보내면 tilt와 zoom은 그대로입니다.</p><p>PTZ에는 <code>get_param</code>이 없습니다. 현재 위치는 <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#rbq-ptz"><code>/rbq/ptz</code></a>에서 읽습니다.</p><h3 id="rbq-ptz-set-service" tabindex="-1"><code>/rbq/ptz/set_service</code> <a class="header-anchor" href="#rbq-ptz-set-service" aria-label="Permalink to &quot;`/rbq/ptz/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;">타입</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">설명</td><td style="text-align:left;">PTZ 동작입니다. 두 이름 모두 <code>true</code>를 보낼 때만 동작합니다.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">이름</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>return_center</code></td><td style="text-align:left;">pan·tilt를 중앙으로 되돌리고 줌을 1×로 맞춥니다</td></tr><tr><td style="text-align:left;"><code>stop</code></td><td style="text-align:left;">pan·tilt 이동을 멈춥니다</td></tr></tbody></table>',49)])])}const f=e(o,[["render",s]]);export{g as __pageData,f as default};
